-- Meero pivot — AI-built WEB APPLICATIONS (secure, production-ready) instead
-- of generative 3D scenes.
--
-- Every plan builds the SAME thing: a real, self-contained, zero-dependency
-- web application (index.html + styles.css + main.ts), generated by the
-- codegen agent and bundled with a real esbuild on a plain Linux worker,
-- then served live through the orchestrator's /preview proxy. A single 'web'
-- build_platform value replaces 'scene' going forward (old rows keep their
-- historical value; enums can't drop values).
--
-- Ultra additionally unlocks a one-click PRODUCTION RELEASE to Vercel — a
-- real deployment through Vercel's REST API, run as a separate, explicitly
-- user-triggered action per build (never part of the base pipeline).
--
-- NOTE: `alter type ... add value` cannot run in the same transaction as a
-- statement that reads/writes a row using the new value.
alter type public.build_platform add value if not exists 'web';

-- build_artifacts.kind: replace the render-specific vocabulary with the new
-- pipeline's artifact kinds. 'source_archive', 'web_bundle', and 'log' are
-- unchanged and reused as-is; 'render_video'/'render_frames' are dropped
-- from the allowed set for NEW rows and 'deployment' (the real Vercel
-- release record) is added. Historical rows already carry old kind values,
-- so the new CHECK is `not valid` — enforced on every future insert/update
-- without scanning the historical backfill (same rationale as 00014).
alter table public.build_artifacts drop constraint build_artifacts_kind_check;
alter table public.build_artifacts add constraint build_artifacts_kind_check
  check (kind in (
    'source_archive',  -- the generated web-app project (html/css/ts), zipped
    'web_bundle',      -- esbuild output actually served as the live preview
    'deployment',      -- ultra: real Vercel production release (metadata holds url/id)
    'log'
  )) not valid;

-- The real production URL of a build's Vercel release. builds is already
-- user-read-only (no user INSERT/UPDATE policies; only the service-role
-- orchestrator writes it), so no extra protection is needed here.
alter table public.builds add column if not exists deploy_url text;

-- Project-level mirror of the most recent release, so the live URL survives
-- newer (undeployed) builds. Non-secret projection for the UI — but written
-- only by the orchestrator after a REAL deployment succeeds, so it gets the
-- same trigger protection as the GitHub repo fields (00008): the owner's own
-- browser client must not be able to fabricate a "live" URL.
alter table public.projects add column if not exists live_url text;

create or replace function public.protect_live_url()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  if auth.role() <> 'service_role' and new.live_url is distinct from old.live_url then
    raise exception 'live_url can only be changed by the orchestrator.';
  end if;
  return new;
end;
$$;

drop trigger if exists projects_protect_live_url on public.projects;
create trigger projects_protect_live_url
  before update on public.projects
  for each row execute function public.protect_live_url();
